using Microsoft.AspNetCore.Diagnostics; using Microsoft.AspNetCore.Mvc; namespace ApiFromLecture.Exceptions; public class GlobalExceptionHandler:IExceptionHandler{readonly ILogger<GlobalExceptionHandler> log; public GlobalExceptionHandler(ILogger<GlobalExceptionHandler> l)=>log=l; public async ValueTask<bool> TryHandleAsync(HttpContext c,Exception ex,CancellationToken ct){log.LogError(ex,"Unhandled exception");var(status,title)=ex switch{KeyNotFoundException=>(404,"Not Found"),ArgumentException=>(400,"Bad Request"),UnauthorizedAccessException=>(403,"Forbidden"),_=>(500,"Internal Server Error")};var p=new ProblemDetails{Status=status,Title=title,Detail=ex.Message,Instance=c.Request.Path};p.Extensions["traceId"]=c.TraceIdentifier;c.Response.StatusCode=status;c.Response.ContentType="application/problem+json";await c.Response.WriteAsJsonAsync(p,ct);return true;}}
